/* bn_ultra_bias.h - ULTRA's bias law. GENERATED by tools/gen_ultra_bias.py from harness/nn_datos.py (BIAS_AXIS) and
 * docs/BIAS_SUPPLY_CIRCUIT.json (the circuit's bias-supply law). DO NOT EDIT: change the sources and regenerate
 * (`make mk81-ultra` checks it). Rows 0 100 W UK, 1 100 W US, 2 50 W UK, 3 50 W US, indexed with variant & 3 (the
 * reissue, variant 4, reads the 100 W UK row). VBIAS: the bias source in volts at bias 0, 0.5 and 1. */
#ifndef BN_ULTRA_BIAS_H
#define BN_ULTRA_BIAS_H
static const double BN_ULTRA_VBIAS[4][3] = {
    { -43.7, -40.19, -37.29 },   /* 100 W UK */
    { -59.09, -55.39, -52.6 },   /* 100 W US */
    { -39.71, -35.64, -32.56 },   /* 50 W UK */
    { -53.18, -49.24, -46.15 },   /* 50 W US */
};
/* the bias source follows the HT load as the circuit's bias rectifier does: its reservoir's
 * relative level z -> 1 - g (I - I_rest), I the averaged HT current, through a first-order lag tau (s); u[2] = vbias x z.
 * [variant][era] (era 0 new way, 1 old way; the 50 W heads have one supply, both columns equal). */
static const double BN_ULTRA_BIASHT_G[4][2] = {
    { 0.03976945020511914, 0.03942537221056051 },
    { 0.042689820664011814, 0.04260173845502369 },
    { 0.059739184185892046, 0.059739184185892046 },
    { 0.05931430851728908, 0.05931430851728908 }
};
static const double BN_ULTRA_BIASHT_TAU[4][2] = {
    { 0.6100000000000003, 0.6100000000000003 },
    { 0.4800000000000004, 0.47000000000000064 },
    { 1.2199999999999998, 1.2199999999999998 },
    { 1.04, 1.04 }
};
/* each variant's htraw-plates resistor, ohms, read off src/ultra/gen_<v>/mks_preamp_mna.h: the averaged rectifier's rchg
 * (the systems carry the rectifier and ULTRA's B+ source is its vsrc). Read only by measurement builds
 * (BN_ULTRA_U1_REPLICA: the supply's reservoir plus this resistor times the rectifier current) */
static const double BN_ULTRA_RHTRAW[4] = { 99.5, 99.5, 150.932, 150.932 };
/* the knob (0..1) to volts, the same piecewise-linear law as nn_datos.py */
static inline double bn_ultra_vbias(int variant, double bias)
{
    const double* a = BN_ULTRA_VBIAS[variant & 3];   /* the reissue (4) reads the 100 W UK row */
    return bias <= 0.5 ? a[0] + (a[1] - a[0]) * (bias / 0.5) : a[1] + (a[2] - a[1]) * ((bias - 0.5) / 0.5);
}
#endif
